package expo.modules.recognitioncpu;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Observed-only enrollment values. No generated truth, filesystem paths or query identity. */
public final class ObservedEnrollment {
 public static final int DIMENSION=1024,MAX_PRODUCTS=10,MAX_ATTEMPTS=64,MAX_EVENTS=4096,PRODUCT_BYTES=32768,STATE_BYTES=360448;
 public static final long CAP=268435456L,RETAINED_PROOFS=44172693L,CAPTURE_RESERVE=25L*1024*1024;
 public static final String ACQUISITION="observed-native-component-enrollment-v1",PROCESSING="native-component-roi-v2-u8-gray128-bilinear224-f32-div255-v1";
 public static final String[] VIEWS={"Front","Rear","Complementary view 1","Complementary view 2"};
 public enum Barcode { UNAVAILABLE, NOT_PRESENTED, UNREADABLE, DECLINED, PENDING, CONFIRMED, CONFLICT }
 public static void require(boolean ok,String code){if(!ok)throw new IllegalStateException(code);}
 public static String hash(byte[] bytes){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder s=new StringBuilder();for(byte x:d)s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}catch(Exception e){throw new IllegalStateException("HASH",e);}}
 static void text(String s,int max){require(s!=null&&!s.isEmpty()&&s.getBytes(StandardCharsets.UTF_8).length<=max&&!s.chars().anyMatch(Character::isISOControl),"TEXT");}
 static void digest(String s){require(s!=null&&s.matches("[0-9a-f]{64}"),"DIGEST");}
 public static String barcodeKey(String raw,String format){int length="ean13".equals(format)?13:"ean8".equals(format)?8:"upc_a".equals(format)?12:0;require(length>0&&raw!=null&&raw.length()==length&&raw.matches("[0-9]+"),"BARCODE_FORMAT");int sum=0,weight=3;for(int i=raw.length()-2;i>=0;i--){sum+=(raw.charAt(i)-'0')*weight;weight=weight==3?1:3;}require((10-sum%10)%10==raw.charAt(raw.length()-1)-'0',"BARCODE_CHECK_DIGIT");return "gtin:"+(length==12?"0"+raw:raw);}
 public static final class Reference {
  public final int job,product,view;public final long epoch;public final String original,crop,geometry,receipt,tensor,rawVector,source,model;private final float[] vector;
  public Reference(int j,int p,int v,long e,String original,String crop,String geometry,String receipt,String tensor,String rawVector,String source,String model,float[] values){
   require(j>=1&&j<=MAX_ATTEMPTS&&p>=0&&p<MAX_PRODUCTS&&v>=0&&v<4&&e>0,"REFERENCE_ID");for(String d:Arrays.asList(original,crop,geometry,receipt,tensor,rawVector,source,model))digest(d);require(values!=null&&values.length==DIMENSION,"VECTOR_DIMENSION");double norm=0;for(float f:values){require(Float.isFinite(f),"VECTOR_FINITE");norm+=(double)f*f;}require(Math.abs(norm-1)<=0.0001,"VECTOR_NORM");
   job=j;product=p;view=v;epoch=e;this.original=original;this.crop=crop;this.geometry=geometry;this.receipt=receipt;this.tensor=tensor;this.rawVector=rawVector;this.source=source;this.model=model;vector=values.clone();
  }
  public float[] vector(){return vector.clone();}
  void write(DataOutputStream d)throws IOException{d.writeInt(job);d.writeInt(product);d.writeInt(view);d.writeLong(epoch);for(String s:Arrays.asList(original,crop,geometry,receipt,tensor,rawVector,source,model))d.writeUTF(s);for(float f:vector)d.writeFloat(f);}
  static Reference read(DataInputStream d)throws IOException{int j=d.readInt(),p=d.readInt(),v=d.readInt();long e=d.readLong();String[] h=new String[8];for(int i=0;i<8;i++){h[i]=d.readUTF();digest(h[i]);}float[] f=new float[DIMENSION];for(int i=0;i<DIMENSION;i++)f[i]=d.readFloat();return new Reference(j,p,v,e,h[0],h[1],h[2],h[3],h[4],h[5],h[6],h[7],f);}
 }
 public static final class Product {
  public final String label;private final Reference[] views=new Reference[4];private Barcode barcode;private String raw="",format="",canonical="";private long barcodeEpoch;
  Product(String label,boolean available){text(label,192);this.label=label;barcode=available?Barcode.NOT_PRESENTED:Barcode.UNAVAILABLE;}
  public Reference view(int slot){require(slot>=0&&slot<4,"VIEW");return views[slot];}
  public Barcode barcode(){return barcode;}public String raw(){return raw;}public long barcodeEpoch(){return barcodeEpoch;}
  public boolean complete(){return Arrays.stream(views).allMatch(Objects::nonNull);}
  void write(DataOutputStream d)throws IOException{d.writeUTF(label);d.writeUTF(barcode.name());d.writeUTF(raw);d.writeUTF(format);d.writeUTF(canonical);d.writeLong(barcodeEpoch);for(Reference ref:views){d.writeBoolean(ref!=null);if(ref!=null)ref.write(d);}}
  byte[] bytes(){try{ByteArrayOutputStream b=new ByteArrayOutputStream();write(new DataOutputStream(b));byte[] bytes=b.toByteArray();require(bytes.length<=PRODUCT_BYTES,"PRODUCT_GALLERY_BYTES");return bytes;}catch(IOException e){throw new IllegalStateException("ENCODE",e);}}
 }
 public static final class Pending {
  public final int job,product,view;public final long epoch;public final String previous;
  Pending(int job,int product,int view,long epoch,String previous){this.job=job;this.product=product;this.view=view;this.epoch=epoch;this.previous=previous;}
 }
 public static final class State {
  private final List<Product> products=new ArrayList<>();private boolean barcodeAvailable;private long epoch;private int attempts,selectedProduct,revision=1;private Pending pending;private Reference candidate;private String interrupted="",frozen="";
  public State(List<String> labels,boolean barcodeAvailable){require(labels!=null&&!labels.isEmpty()&&labels.size()<=MAX_PRODUCTS,"ROSTER_COUNT");require(new HashSet<>(labels).size()==labels.size(),"ROSTER_DUPLICATE");this.barcodeAvailable=barcodeAvailable;for(String s:labels)products.add(new Product(s,barcodeAvailable));}
  public boolean barcodeAvailable(){return barcodeAvailable;}
  public void enableBarcodes(){editable();require(pending==null&&candidate==null&&!barcodeAvailable,"BARCODE_ENABLE_STATE");barcodeAvailable=true;for(Product p:products){require(p.barcode==Barcode.UNAVAILABLE,"BARCODE_ENABLE_STATE");p.barcode=Barcode.NOT_PRESENTED;}epoch++;}
  public long beginBarcodeScan(int p,int view,String previous){editable();require(barcodeAvailable&&pending==null&&candidate==null&&p==selectedProduct&&products.stream().noneMatch(x->x.barcode==Barcode.PENDING),"BARCODE_SCAN_STATE");require(view>=0&&view<4,"VIEW");Reference ref=product(p).view(view);require((ref==null?"":ref.receipt).equals(previous),"REPLACEMENT_STALE");epoch++;return epoch;}
  public void barcodeDisposition(int p,long expectedEpoch,Barcode value){editable();require(barcodeAvailable&&p==selectedProduct&&epoch==expectedEpoch&&pending==null&&candidate==null,"BARCODE_STALE");require(value==Barcode.NOT_PRESENTED||value==Barcode.UNREADABLE||value==Barcode.DECLINED,"BARCODE_DISPOSITION");Product product=product(p);require(product.barcode!=Barcode.PENDING,"BARCODE_PENDING");product.barcode=value;product.raw="";product.format="";product.canonical="";product.barcodeEpoch=expectedEpoch;}
  public List<Product> products(){return Collections.unmodifiableList(products);}public long epoch(){return epoch;}public int attempts(){return attempts;}public int revision(){return revision;}public int selectedProduct(){return selectedProduct;} public void select(int p){editable();product(p);require(pending==null&&candidate==null&&products.stream().noneMatch(x->x.barcode==Barcode.PENDING),"SELECTION_BUSY");selectedProduct=p;epoch++;}public Pending pending(){return pending;}public Reference candidate(){return candidate;}public String interrupted(){return interrupted;}public String frozen(){return frozen;}
  private void editable(){require(frozen.isEmpty(),"FROZEN_NEW_REVISION_REQUIRED");}
  private Product product(int p){require(p>=0&&p<products.size(),"PRODUCT");return products.get(p);}
  public Pending begin(int p,int view,String expectedOld,long used,long free){editable();require(pending==null&&candidate==null,"WORK_OR_REVIEW_PENDING");require(p==selectedProduct&&products.stream().noneMatch(x->x.barcode==Barcode.PENDING),"PRODUCT_SELECTION_OR_BARCODE_BUSY");Product product=product(p);require(view>=0&&view<4,"VIEW");Reference old=product.views[view];require((old==null?"":old.receipt).equals(expectedOld),"REPLACEMENT_STALE");if(old==null)for(int i=0;i<view;i++)require(product.views[i]!=null,"VIEW_ORDER");require(attempts<MAX_ATTEMPTS,"ATTEMPT_LIMIT");require(used>=RETAINED_PROOFS&&used<=CAP-CAPTURE_RESERVE-STATE_BYTES&&free>=256L*1024*1024+CAPTURE_RESERVE+STATE_BYTES,"QUOTA");epoch++;attempts++;pending=new Pending(attempts,p,view,epoch,expectedOld);interrupted="";return pending;}
  public void offer(Reference ref){editable();require(pending!=null&&candidate==null,"NO_PENDING");require(ref.job==pending.job&&ref.product==pending.product&&ref.view==pending.view&&ref.epoch==pending.epoch,"STALE_REFERENCE");require(ref.model.equals(CameraProofFrame.MODEL),"MODEL");candidate=ref;pending=null;require(product(ref.product).bytes().length+referenceBytes(ref).length<PRODUCT_BYTES,"PRODUCT_WITH_REVIEW_BYTES");}
  public void keep(int job,long expectedEpoch){editable();require(candidate!=null&&candidate.job==job&&candidate.epoch==expectedEpoch,"STALE_REVIEW");Product p=product(candidate.product);p.views[candidate.view]=candidate;p.bytes();candidate=null;}
  public void decline(int job,long expectedEpoch){editable();require(candidate!=null&&candidate.job==job&&candidate.epoch==expectedEpoch,"STALE_REVIEW");interrupted="DECLINED:"+job;candidate=null;}
  public void interrupt(int job,long expectedEpoch){editable();require(pending!=null&&pending.job==job&&pending.epoch==expectedEpoch,"STALE_INTERRUPT");interrupted="INTERRUPTED:"+job;pending=null;epoch++;}
  public void barcodeCandidate(int p,long expectedEpoch,String raw,String format,String canonical){editable();require(barcodeAvailable,"BARCODE_UNAVAILABLE");require(pending==null&&candidate==null&&epoch==expectedEpoch,"BARCODE_STALE_OR_BUSY");text(raw,128);text(format,32);require(p==selectedProduct&&barcodeKey(raw,format).equals(canonical),"BARCODE_CANONICAL");Product product=product(p);require(product.barcode!=Barcode.PENDING&&product.barcodeEpoch!=expectedEpoch,"BARCODE_PENDING_OR_DUPLICATE");product.raw=raw;product.format=format;product.canonical=canonical;product.barcodeEpoch=expectedEpoch;product.barcode=Barcode.PENDING;}
  public void confirmBarcode(int p,long expectedEpoch,boolean accept){editable();Product product=product(p);require(p==selectedProduct&&pending==null&&candidate==null&&epoch==expectedEpoch&&product.barcodeEpoch==expectedEpoch&&product.barcode==Barcode.PENDING,"BARCODE_STALE");if(!accept){product.barcode=Barcode.DECLINED;return;}for(Product other:products)if(other!=product&&other.barcode==Barcode.CONFIRMED&&other.canonical.equals(product.canonical)){product.barcode=Barcode.CONFLICT;return;}product.barcode=Barcode.CONFIRMED;}
  public void freeze(){editable();require(pending==null&&candidate==null,"FREEZE_BUSY");for(Product p:products){require(p.complete()&&p.barcode!=Barcode.PENDING&&p.barcode!=Barcode.CONFLICT,"GALLERY_INCOMPLETE");p.bytes();}frozen=hash(galleryBytes());}
  public void newRevision(){require(!frozen.isEmpty(),"NOT_FROZEN");require(revision<Integer.MAX_VALUE,"REVISION_LIMIT");revision++;frozen="";epoch++;}
  public byte[] galleryBytes(){try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeUTF(ACQUISITION);d.writeUTF(PROCESSING);d.writeInt(revision);d.writeInt(products.size());for(Product p:products){byte[] bytes=p.bytes();d.writeInt(bytes.length);d.write(bytes);}return b.toByteArray();}catch(IOException e){throw new IllegalStateException("GALLERY_ENCODE",e);}}
  public byte[] bytes(){try{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeInt(1);d.writeBoolean(barcodeAvailable);d.writeLong(epoch);d.writeInt(attempts);d.writeUTF(interrupted);d.writeUTF(frozen);d.writeInt(revision);d.writeInt(selectedProduct);d.writeInt(products.size());for(Product p:products)p.write(d);d.writeBoolean(pending!=null);if(pending!=null){d.writeInt(pending.job);d.writeInt(pending.product);d.writeInt(pending.view);d.writeLong(pending.epoch);d.writeUTF(pending.previous);}d.writeBoolean(candidate!=null);if(candidate!=null)candidate.write(d);byte[] bytes=b.toByteArray();require(bytes.length<=STATE_BYTES,"STATE_BYTES");return bytes;}catch(IOException e){throw new IllegalStateException("ENCODE",e);}}
  public static State read(byte[] bytes){require(bytes!=null&&bytes.length>0&&bytes.length<=STATE_BYTES,"STATE_BYTES");try{DataInputStream d=new DataInputStream(new ByteArrayInputStream(bytes));require(d.readInt()==1,"STATE_VERSION");boolean available=d.readBoolean();long epoch=d.readLong();int attempts=d.readInt();String interrupted=d.readUTF(),frozen=d.readUTF();int revision=d.readInt(),selected=d.readInt(),count=d.readInt();require(count>=1&&count<=MAX_PRODUCTS&&epoch>=0&&attempts>=0&&attempts<=MAX_ATTEMPTS&&revision>=1&&selected>=0&&selected<count,"STATE_HEADER");State s=new State(Arrays.asList("temporary"),available);s.products.clear();s.epoch=epoch;s.attempts=attempts;s.interrupted=interrupted;s.frozen=frozen;s.revision=revision;s.selectedProduct=selected;require(interrupted.isEmpty()||interrupted.matches("(INTERRUPTED|DECLINED):[0-9]{1,2}"),"INTERRUPTION_LABEL");Set<Integer> jobs=new HashSet<>();Set<String> labels=new HashSet<>(),confirmedCodes=new HashSet<>();
   for(int p=0;p<count;p++){Product product=new Product(d.readUTF(),available);require(labels.add(product.label),"ROSTER_DUPLICATE");product.barcode=Barcode.valueOf(d.readUTF());product.raw=d.readUTF();product.format=d.readUTF();product.canonical=d.readUTF();product.barcodeEpoch=d.readLong();require(available||(product.barcode==Barcode.UNAVAILABLE&&product.barcodeEpoch==0),"BARCODE_GATE");require(product.barcodeEpoch>=0&&product.barcodeEpoch<=epoch,"BARCODE_EPOCH");if(product.barcode==Barcode.CONFIRMED)require(confirmedCodes.add(product.canonical),"BARCODE_DUPLICATE_CONFIRMED");require(!available||product.barcode!=Barcode.UNAVAILABLE,"BARCODE_GATE");if(product.barcode==Barcode.PENDING||product.barcode==Barcode.CONFIRMED||product.barcode==Barcode.CONFLICT)require(!product.canonical.isEmpty()&&product.barcodeEpoch>0,"BARCODE_VALUE");if(product.barcode==Barcode.PENDING)require(p==selected&&product.barcodeEpoch==epoch,"BARCODE_PENDING_OWNER");if(product.barcode==Barcode.UNAVAILABLE||product.barcode==Barcode.NOT_PRESENTED||product.barcode==Barcode.UNREADABLE)require(product.raw.isEmpty()&&product.format.isEmpty()&&product.canonical.isEmpty(),"BARCODE_EMPTY_DISPOSITION");require(product.raw.getBytes(StandardCharsets.UTF_8).length<=128&&product.format.length()<=32&&(product.canonical.isEmpty()||product.canonical.equals(barcodeKey(product.raw,product.format))),"BARCODE_BOUNDS");for(int v=0;v<4;v++)if(d.readBoolean()){Reference ref=Reference.read(d);require(ref.product==p&&ref.view==v&&ref.job<=attempts&&ref.epoch<=epoch&&ref.model.equals(CameraProofFrame.MODEL)&&jobs.add(ref.job),"REFERENCE_BINDING");product.views[v]=ref;}boolean gap=false;for(Reference ref:product.views){if(ref==null)gap=true;else require(!gap,"VIEW_ORDER");}product.bytes();s.products.add(product);}
   if(d.readBoolean()){int job=d.readInt(),p=d.readInt(),v=d.readInt();long e=d.readLong();String previous=d.readUTF();require(job==attempts&&p>=0&&p<count&&p==selected&&v>=0&&v<4&&e==epoch&&e>0&&!jobs.contains(job),"PENDING_BINDING");Reference old=s.products.get(p).views[v];require(previous.equals(old==null?"":old.receipt),"PENDING_PREVIOUS");for(int earlier=0;earlier<v;earlier++)require(s.products.get(p).views[earlier]!=null,"VIEW_ORDER");s.pending=new Pending(job,p,v,e,previous);}
   if(d.readBoolean()){s.candidate=Reference.read(d);require(s.pending==null&&s.candidate.job==attempts&&s.candidate.epoch==epoch&&s.candidate.product<count&&s.candidate.product==selected&&s.candidate.model.equals(CameraProofFrame.MODEL)&&!jobs.contains(s.candidate.job),"CANDIDATE_BINDING");for(int earlier=0;earlier<s.candidate.view;earlier++)require(s.products.get(selected).views[earlier]!=null,"VIEW_ORDER");}
   require(interrupted.isEmpty()||(Integer.parseInt(interrupted.substring(interrupted.indexOf(':')+1))>=1&&Integer.parseInt(interrupted.substring(interrupted.indexOf(':')+1))<=attempts),"INTERRUPTION_BINDING");require(d.available()==0,"STATE_TRAILING");if(!frozen.isEmpty()){digest(frozen);require(s.pending==null&&s.candidate==null&&s.products.stream().allMatch(x->x.complete()&&x.barcode!=Barcode.PENDING&&x.barcode!=Barcode.CONFLICT)&&hash(s.galleryBytes()).equals(frozen),"FREEZE_HASH");}require(Arrays.equals(bytes,s.bytes()),"STATE_CANONICAL");return s;
  }catch(IOException|IllegalArgumentException e){throw new IllegalStateException("STATE_DECODE",e);}}
 }
 static byte[] referenceBytes(Reference ref){try{ByteArrayOutputStream b=new ByteArrayOutputStream();ref.write(new DataOutputStream(b));return b.toByteArray();}catch(IOException e){throw new IllegalStateException("REFERENCE_ENCODE",e);}}
}
